def vector(path, mirrored):
    return f'''<?xml version="1.0" encoding="utf-8"?>
<vector xmlns:android="http://schemas.android.com/apk/res/android"
    android:width="24dp" android:height="24dp" android:viewportWidth="24" android:viewportHeight="24"{' android:autoMirrored="true"' if mirrored else ''}>
    <path android:fillColor="#FFFFFFFF" android:pathData="{path}"/>
</vector>
'''

def main():
    os.makedirs(RES, exist_ok=True)
    for name, (path, mir) in ICONS.items():
        with open(os.path.join(RES, f"ic_{name}.xml"), "w") as f:
            f.write(vector(path, mir))
    os.makedirs(os.path.join(ROOT, "build"), exist_ok=True)
    cells = "".join(f'<div class="c"><svg viewBox="0 0 24 24" width="48" height="48"><path d="{p}"/></svg><div>{n}</div></div>' for n, (p, _) in ICONS.items())
    html = f'<html><body style="font-family:sans-serif;display:flex;flex-wrap:wrap;width:900px">{cells}<style>.c{{width:100px;height:90px;text-align:center;font-size:11px}} svg{{fill:#1F3A5F}}</style></body></html>'
    with open(os.path.join(ROOT, "build/icons.html"), "w") as f:
        f.write(html)
    print(f"{len(ICONS)} icons")

if __name__ == "__main__":
    main()
